$projects = @("daily-brief", "knowledge", "mimic", "sumzy"); foreach ($proj in $projects) { Write-Output "`n=== Project: $proj ==="; Set-Location "$env:USERPROFILE\AI_PROJECTS\projects\$proj"; $changes = git status --porcelain 2>&1 | Out-String; if ($changes -match '\d+ changes to be committed') { Write-Output "$proj has changes:"; $changes; } else { if ($changes) { Write-Output "Uncommitted changes detected:"; $changes; # Stage all changes
Write-Output "Staging changes...";
if (git add . 2>&1) {
    Write-Output "Committing..."
    git commit -m "auto-sync: heartbeat update"
}
# Push to remote
if (git push --atomic 2>&1 | Out-String) {
    Write-Output "Push successful."
} else {
    Write-Output "Note: No remote configured or push failed.";
}
} else { Write-Output "No uncommitted changes." } } }
